-- Audio Engine loader: procedural engine sound + rpm/speed HUD for registered cars
AUDIO_ENGINE = AUDIO_ENGINE or {}

local folder = "audio_engine/"
local sharedFiles = { "sh_config.lua", "sh_presets.lua", "sh_drivetrain.lua", "sh_carlist.lua", "sh_perp.lua", "sh_police.lua" }
-- cl_baked.lua: generated by dev/baker (what the pre-generated sounds in sound/audio_engine/ are)
local clientFiles = { "cl_baked.lua", "cl_synth.lua", "cl_soundbank.lua", "cl_engine.lua", "cl_hud.lua", "cl_menu.lua", "cl_police.lua" }

if SERVER then
	for _, fileName in ipairs(sharedFiles) do AddCSLuaFile(folder .. fileName) end
	for _, fileName in ipairs(clientFiles) do AddCSLuaFile(folder .. fileName) end
end

for _, fileName in ipairs(sharedFiles) do include(folder .. fileName) end

if SERVER then
	include(folder .. "sv_perp_physics.lua")   -- generated: PERP's base-script physics per car
	include(folder .. "sv_handling.lua")
	include(folder .. "sv_engine.lua")
	include(folder .. "sv_stability.lua")
	include(folder .. "sv_cruise.lua")
	include(folder .. "sv_police.lua")
	include(folder .. "sv_seats.lua")
else
	for _, fileName in ipairs(clientFiles) do include(folder .. fileName) end
end

-- the debug tools (lua/audio_engine_debug/: script, gearing and rev editors, handling switches;
-- superadmins, audio_engine_debug). Loaded whenever the folder is there: to ship the addon
-- without them, delete the folder, nothing else
local debugFolder = "audio_engine_debug/"
if file.Exists(debugFolder .. "sh_debug.lua", "LUA") then
	if SERVER then
		for _, fileName in ipairs({ "sh_kv.lua", "sh_debug.lua", "cl_debug.lua", "cl_perf.lua" }) do AddCSLuaFile(debugFolder .. fileName) end
	end
	include(debugFolder .. "sh_kv.lua")
	include(debugFolder .. "sh_debug.lua")
	include(debugFolder .. (SERVER and "sv_debug.lua" or "cl_debug.lua"))
	-- the profiler (audio_engine_perf, audio_engine_perf_hud): measures nothing until it's turned on
	include(debugFolder .. (SERVER and "sv_perf.lua" or "cl_perf.lua"))
end
